/**
 * 从子树进行删除的内部方法.
 * x 是要被删除的项.
 * t 是该树的根节点.
 * 建立子树新的根.
 */
void remove( const Comparable & x, TreapNode * & t )
{
    if( t != nullNode )
    {
        if( x < t->element )
            remove( x, t->left );
        else if( t->element < x )
            remove( x, t->right );
        else
        {
            // 找到匹配
            if( t->left->priority < t->right->priority )
                rotateWithLeftChild( t );
            else
                rotateWithRightChild( t );

            if( t != nullNode )      // 继续下行
                remove( x, t );
            else
            {
                delete t->left;
                t->left = nullNode;  // 在叶节点上
            }
        }
    }
}
